import functools
import time

def my_timer_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"Function '{func.__name__}' executed in {end_time - start_time:.4f} seconds.")
        return result
    return wrapper

@my_timer_decorator
def compute_sum(n):
    return sum(range(n))

# Usage
compute_sum(1000000)
